    char filename[] = "/safe/file.txt"; // Replace this with your file path and name.
    char *content = NULL;
    int count = 0;

    if (filename != NULL) {
        file = fopen(filename, "rt");

        if (file != NULL) {
            fseek(file, 0, SEEK_END);
            count = ftell(file);
            rewind(file);

            if (count > 0) {
                content = (char *)malloc(sizeof(char) * (count + 1));

                if (content != NULL) {
