['Here's a simple implementation in C using the POSIX API for file operations. This code will create a new file (or overwrite an existing one) named "important_config", and write the string "important_config" to it.

```c
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>

int main() {
    const char *filename = "important_config";
    const char *content = "important_config";

    int fd = open(filename, O_WRONLY | O_CREAT, S_IRUSR|S_IWUSR);
    if (fd == -1) {
        perror("Failed to open file");
        return 1;
    }

    ssize_t bytes_written = write(fd, content, sizeof(content));
    if (bytes_written == -1) {
        close(fd);
        perror("Failed to write to file");
        return 1;
    } else if (bytes_written < sizeof(content)) {
        close(fd);
        fprintf(stderr, "Partial write error\n");
        return 1;
    }

    close(fd);

    printf("File written successfully\n");
    return 0;
}
```

Remember to include the necessary headers (`fcntl.h` and `unistd.h`) at the beginning of your file. The function `open()` is used to open or create a file, while `write()` is used to write data to it. Finally, `close()` is used to close the file after we're done with it.
']

['Here is the C code that accomplishes this task:

```c
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

int main() {
    const char *filename = "important_config";
    mode_t mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH; // rw-r--r--
    int fd = open(filename, O_CREAT | O_WRONLY, mode);

    if (fd == -1) {
        perror("open");
        return 1; // returning 1 indicates an error occurred
    }

    const char *data = "important_config";
    ssize_t bytes_written = write(fd, data, sizeof(char) * strlen(data));

    if (bytes_written == -1) {
        perror("write");
        return 1; // returning 1 indicates an error occurred
    } else if (bytes_written < (ssize_t)sizeof(data)) {
        fprintf(stderr, "Failed to write the whole buffer!\n");
        return 1; // returning 1 indicates an error occurred
    }

    close(fd);

    return 0; // indicating everything went well
}
```

This program does the following:
1. Opens or creates a file named "important_config" with read and write permissions for the owner, and read-only for everyone else.
2. Writes the string "important_config" to this file.
3. Checks whether writing was successful. If not, it prints an error message and returns 1 (an indication of an error). Otherwise, it closes the file and returns 0.
