['Here is a simple example of how you can use these flags in C language with open() function. This program creates a new file named "example.txt" and writes some text into it. If the file already exists, it truncates it and overwrites its content.

```c
#include <fcntl.h>
#include <unistd.h>

int main() {
    int fd = open("example.txt", O_CREAT | O_WRONLY | O_TRUNC, 0644);

    if(fd == -1) {
        write(STDERR_FILENO, "Cannot create or truncate file\n", 29);
        return 1;
    }

    const char* text = "This is some text to be written into the file.";
    ssize_t length = write(fd, text, sizeof(char) * strlen(text));

    if(length == -1) {
        write(STDERR_FILENO, "Cannot write data into file\n", 27);
        return 1;
    } else {
        write(STDOUT_FILENO, "Data has been written successfully.\n", 34);
    }

    close(fd);
    return 0;
