#include <stdlib.h>

int run_command(const char *username) {
    // Construct the command string
    int size = snprintf(NULL, 0, "id %s", username) + 1;
    if (size <= 0) {
        perror("snprintf failed");
        return -1;
    }
    char *command = malloc(size);
    snprintf(command, size, "id %s", username);

    // Run the command and check its exit status
    int result = system(command);
    free(command);

    if (result < 0) {
        perror("system call failed");
        return -1;
    } else {
        printf("Exit status: %d\n", WEXITSTATUS(result));
        return WEXITSTATUS(result);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <username>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int status = run_command(argv[1]);

    if (status == 0) {
        printf("Command executed successfully.\n");
    } else {
        fprintf(stderr, "Command failed with exit status %d\n", status);
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

This program takes a username as a command line argument and runs the `id` command for that user. It prints out the exit status of the command, and returns an appropriate error code if the command fails.
