['Here's an example of how you might implement these functions in C:

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

char* escape_html(const char *str) {
    int len = strlen(str);
    char *escapedStr = malloc((len * 2 + 1) * sizeof(char)); // Worst case scenario: no escapes needed

    for (int i = 0, j = 0; i < len; ++i, ++j) {
        switch (str[i]) {
            case '<': strcpy(&escapedStr[j], "&lt;"); j += 3; break;
            case '>': strcpy(&escapedStr[j], "&gt;"); j += 3; break;
            case '&': strcpy(&escapedStr[j], "&amp;"); j += 4; break;
            default: escapedStr[j] = str[i];
        }
    }

    return escapedStr;
}

void http_hello_page(FILE *request, FILE *response) {
    char username[256]; // Adjust as needed.

    fscanf(request, "%s", username);
    char* escapedUsername = escape_html(username);

    fprintf(response, "HTTP/1.0 200 OK\nContent-Type: text/plain\nContent-Length: %zu\n\n", strlen(escapedUsername));
    fputs("hello ", response);
    fputs(escapedUsername, response);

    free(escapedUsername); // Don't forget to free the memory allocated by escape_html function
}
```
This code is a very basic implementation and lacks any kind of error checking or input sanitization. It also doesn't handle HTTP headers or other parts of the request/response properly, but it should give you a starting point for your own implementation. Please adjust to fit with your requirements.
